function beep(){try{if(navigator.vibrate)navigator.vibrate([200,100,200,100,400])}catch(e){}if(!S.p.beep)return;try{const a=ac(),T=[0,.22,.44,.66,.95],F=[784,784,784,784,1175];T.forEach((t,i)=>{const o=a.createOscillator(),g=a.createGain(),d=i==4?.5:.16;o.type='square';o.frequency.value=F[i];g.gain.setValueAtTime(.0001,a.currentTime+t);g.gain.exponentialRampToValueAtTime(.25,a.currentTime+t+.01);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+t+d);o.connect(g);g.connect(a.destination);o.start(a.currentTime+t);o.stop(a.currentTime+t+d+.02)})}catch(e){}}
