 for(let i=1;i<=N(t);i++){const k=key(new Date(t.getFullYear(),t.getMonth(),i));v.push(S.pct[k]||0);l.push(i)}
 const hist=Object.keys(S.done).filter(k=>S.done[k].length).sort().reverse().slice(0,30);
