const EXACT=['Dos','Mode','Tous','Bras','Abdos','Tronc','Jambes','Cheveux','Poitrine','Épaules','Fessiers','Mollets','Mobilité','Âge','Durée','Programme','Exercices','Accueil','Profil','Terminer','Commencer','Démarrer','Continuer','Passer','Départ','Arrivée','Étapes','Clair','Sombre','Automatique','Récupération','Respiration','Sécurité','Semaine','Bonjour'];
const EK=Object.keys(EN).sort((a,b)=>b.length-a.length);
function trPage(){if(S.p.lang!=='en'||typeof document.createTreeWalker!=='function')return;for(const id of ['#v','#nav','#ov']){const r=$(id);if(!r)continue;const w=document.createTreeWalker(r,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode())){let t=n.nodeValue;const o=t;for(const k of EK){if(EXACT.includes(k)){if(t.trim()===k)t=t.replace(k,EN[k])}else if(t.includes(k))t=t.split(k).join(EN[k])}if(t!==o)n.nodeValue=t}}}
const _fi=fiche;fiche=id=>{_fi(id);trPage()};
document.documentElement.lang=S.p.lang;
lockUI();
